<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api} from './api'
const emit=defineEmits<{error:[string],notice:[string]}>()
const cfg=ref<any>(null),busy=ref(false),status=ref<any>(null),hosts=ref('')
const apiFields=[['cfg_wisemed_ip','Server WiseMED'],['cfg_wisemed_port','Port'],['cfg_wisemed_path','Cale API'],['unitate_medicala_id','ID unitate medicală'],['tip_de_echipament_id','ID tip echipament'],['cod_echipament','Cod utilitar/echipament'],['numar_serial_echipament','Număr serial']]
const wsFields=[['tenant_id','Tenant WSM'],['key_id','ID cheie'],['issuer','Emitent'],['audience','Audiență'],['subject','Subiect'],['client_id','ID client/instanță']]
const scopes=['route:reply','route:event','route:command','devices:debug','connections:read','server:status','api:invoke','api:admin','route:broadcast','topics:subscribe','wisemed:proxy']
const selectedScopes=ref<string[]>([])
async function load(){cfg.value=await api('runtime-settings');for(const section of ['wisemed-api','wisemed-ws','app-updates','wisemed-ai'])cfg.value[section] ||= {};hosts.value=(cfg.value['wisemed-ai'].connector_allowed_hosts||[]).join('\n');selectedScopes.value=(cfg.value['wisemed-ws'].scopes||'').split(',').filter(Boolean)}
async function save(){busy.value=true;try{const sections:any={};for(const section of ['wisemed-api','wisemed-ws','app-updates','wisemed-ai']){sections[section]={};for(const [key,value]of Object.entries(cfg.value[section]))if(!key.endsWith('_configured')&&value!==undefined)sections[section][key]=value}sections['wisemed-ws'].scopes=selectedScopes.value.join(',');sections['wisemed-ai'].connector_allowed_hosts=hosts.value.split('\n').map(h=>h.trim()).filter(Boolean);await api('runtime-settings','PUT',{sections});emit('notice','Configurațiile au fost salvate. Reporniți utilitarul pentru API, PostgreSQL, HTTPS cookie și actualizări. WSM încearcă reconectarea prin adaptorul comun.');await load()}catch(e){emit('error',String(e))}finally{busy.value=false}}
async function checkUpdates(){busy.value=true;try{status.value=await api('updates/check','POST',{})}catch(e){emit('error',String(e))}finally{busy.value=false}}
async function reconnect(){busy.value=true;try{await api('wsm/reconnect','POST',{});emit('notice','Reconectare WSM solicitată. Conectarea cere un ID WiseMED valid și permisiuni provisionate.')}catch(e){emit('error',String(e))}finally{busy.value=false}}
onMounted(async()=>{try{await load()}catch(e){emit('error',String(e))}})
</script>
<template><template v-if="cfg"><div class="section-heading"><h2>Configurare completă a utilitarului</h2><Button label="Salvează API, WSM și infrastructură" icon="pi pi-save" @click="save" :loading="busy"/></div><div class="two"><section class="paper"><h2>WiseMED API</h2><p class="muted small">Protocolul existent: HTTPS, JWT de aplicație și autentificare server-to-server. Nicio identitate clinică nu este creată automat.</p><label>Protocol<Select v-model="cfg['wisemed-api'].cfg_wisemed_protocol" :options="['https']"/></label><label v-for="field in apiFields" :key="field[0]">{{field[1]}}<InputText v-model="cfg['wisemed-api'][field[0]]"/></label><label>Cheie WiseMED API · {{cfg['wisemed-api'].cfg_wisemed_key_configured?'configurată':'neconfigurată'}}<InputText type="password" v-model="cfg['wisemed-api'].cfg_wisemed_key" autocomplete="new-password" placeholder="Gol păstrează cheia salvată"/></label><label class="check"><input type="checkbox" v-model="cfg['wisemed-ai'].wisemed_login_enabled"/> Permite login WiseMED cu mapping explicit de identități</label></section><section class="paper"><h2>WSM / WSS</h2><label class="check"><input type="checkbox" v-model="cfg['wisemed-ws'].enabled"/> Activează transportul opțional</label><label>Adresă WSS<InputText v-model="cfg['wisemed-ws'].url" placeholder="wss://wslocal.wisemed.eu/ws"/></label><label>Autentificare<Select v-model="cfg['wisemed-ws'].auth_mode" :options="['device_key','token_file','token_endpoint']"/></label><template v-if="cfg['wisemed-ws'].auth_mode==='device_key'"><label v-for="field in wsFields" :key="field[0]">{{field[1]}}<InputText v-model="cfg['wisemed-ws'][field[0]]"/></label><label>Cheie echipament · {{cfg['wisemed-ws'].device_secret_configured?'configurată':'neconfigurată'}}<InputText type="password" v-model="cfg['wisemed-ws'].device_secret" autocomplete="new-password" placeholder="Minimum 32 bytes; gol păstrează cheia"/></label><label>Fișier cheie (alternativă)<InputText v-model="cfg['wisemed-ws'].secret_file"/></label></template><label v-if="cfg['wisemed-ws'].auth_mode==='token_file'">Fișier JWT<InputText v-model="cfg['wisemed-ws'].token_file"/></label><label v-if="cfg['wisemed-ws'].auth_mode==='token_endpoint'">Cale endpoint JWT WiseMED<InputText v-model="cfg['wisemed-ws'].token_path"/></label><label>Fișier CA suplimentar<InputText v-model="cfg['wisemed-ws'].ca_file"/></label><details><summary>Permisiuni solicitate · {{selectedScopes.length}}</summary><p class="small muted">Selectarea nu acordă drepturi. Cheia WSM provisionată trebuie să le permită.</p><label v-for="scope in scopes" class="check"><input type="checkbox" v-model="selectedScopes" :value="scope"/>{{scope}}</label></details><label class="check"><input type="checkbox" v-model="cfg['wisemed-ai'].wsm_identity_enabled"/> Acceptă identități WSM verificate și mapate în organizație</label><Button label="Reconectează WSM" icon="pi pi-refresh" severity="secondary" @click="reconnect" :loading="busy"/><details v-if="cfg.wsm_status"><summary>Stare WSM</summary><pre>{{JSON.stringify(cfg.wsm_status,null,2)}}</pre></details></section></div><div class="two"><section class="paper"><h2>PostgreSQL și conectori</h2><p class="small muted">Tabelele proprii au prefix wai_. Conexiunea poate fi suprascrisă de WISEMED_AI_DATABASE_URL. Nu este returnată în clar.</p><label>DSN PostgreSQL · {{cfg['wisemed-ai'].database_url_configured?'configurat':'folosiți env sau introduceți conexiunea'}}<InputText type="password" v-model="cfg['wisemed-ai'].database_url" autocomplete="new-password" placeholder="postgres://user:password@host:5432/database?sslmode=verify-full"/></label><label>Gazde HTTPS permise pentru livrare (host[:port], o gazdă pe linie)<Textarea v-model="hosts" rows="4" placeholder="his.example.ro&#10;odoo.example.ro:443"/></label><label class="check"><input type="checkbox" v-model="cfg['wisemed-ai'].secure_cookies"/> Cookie Secure · activați împreună cu HTTPS</label><p class="small muted">Cheia de criptare și parolele inițiale rămân în fișierele locale protejate din deployments.</p></section><section class="paper"><h2>Actualizări automate</h2><p class="small muted">Versiune instalată: {{cfg.version}} · mecanism comun WiseMED Lab Readers</p><label class="check"><input type="checkbox" v-model="cfg['app-updates'].enabled"/> Verifică actualizările</label><label>App ID<InputText v-model="cfg['app-updates'].app_id" readonly/></label><label>Canal<Select v-model="cfg['app-updates'].channel" :options="['stable','beta']"/></label><label>Update-server<InputText v-model="cfg['app-updates'].base_url"/></label><label class="check"><input type="checkbox" v-model="cfg['app-updates'].auto_download"/> Descarcă automat</label><label>Director descărcări<InputText v-model="cfg['app-updates'].download_dir"/></label><Button label="Verifică actualizările acum" icon="pi pi-refresh" severity="secondary" @click="checkUpdates" :loading="busy"/><pre v-if="status">{{JSON.stringify(status,null,2)}}</pre></section></div></template></template>
